class StorageFullError extends Error{}
// Persist the whole state. If the browser refuses (usually storage quota), roll the in-memory state back to the
// last saved copy so the screen never shows changes that would be lost on reload, then report the failure.
function save(){
  try{saveState(localStorage,state);}
  catch(error){
    let restored;try{restored=JSON.parse(localStorage.getItem(storageKey)||'null');}catch{restored=null;}
    for(const k of Object.keys(state))delete state[k];
    Object.assign(state,normalizeState(restored&&Array.isArray(restored.matters)&&Array.isArray(restored.payments)?restored:seed()));
    state.serviceCategories??=structuredClone(defaultCategories);
    closeModal();shell();
    const message='Not saved: browser storage is full. Remove large sample images or reset the demo, then try again.';
    toast(message);
    throw new StorageFullError(message);
  }
}
window.addEventListener('error',e=>{if(e.error instanceof StorageFullError)e.preventDefault();});
