function head(eyebrow,title,subtitle,action='',actionLabel=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action?`<div class="head-actions"><button class="btn primary" data-action="${action}">${icon('plus')}<span class="btn-label">${esc(actionLabel)}</span></button></div>`:''}</div>`}
function stat(ic,label,num,note,color='',destination='',initialFilter='All'){const tagName=destination?'button':'div';return `<${tagName} class="card stat ${destination?'stat-link':''}" ${destination?`type="button" data-page="${destination}" data-filter="${initialFilter}" aria-label="View ${esc(label)}"`:''}><div class="stat-top"><span>${label}</span><span class="icon-box ${color}">${icon(ic)}</span></div><div class="stat-value">${num}</div><div class="stat-note">${note}</div></${tagName}>`}
function taskRows(tasks,limit=99){const items=tasks.filter(x=>!x.done).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,limit);return items.length?items.map(t=>`<div class="task"><div class="task-dot"></div><div><div class="task-title">${value(t.title)}</div><div class="task-detail">${value(t.related)} · ${value(t.assigned)}</div></div><div class="task-date ${t.dueDate<today()?'overdue':''}">${esc(dateLabel(t.dueDate))}</div></div>`).join(''):'<div class="empty">No open reminders.</div>';}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No matching records found.</td></tr>`}</tbody></table></div>`}
