function inquiries(){const a=state.inquiries.filter(x=>match(x.id,x.name,x.email,x.phone,x.whatsapp,x.profession,x.country,x.district,x.city,x.service,x.purposeCountry,x.purpose,x.channel));return head('Intake','Website Inquiries','Review website contacts and move qualified inquiries to leads.','new-inquiry','Add inquiry')+`<div class="callout">Website connection is not active. Use fictional sample information only.</div><div class="card" style="padding:12px"><label><input type="checkbox" id="inquiry-select-all"> Select all visible</label> <button class="btn small" data-action="delete-selected-inquiries">Delete selected</button></div><div class="card inquiry-list-table">${table(['Select','Web Contact ID','Full name','Profession','Date & time','Mobile / WhatsApp','Email','Country','District / City','Service / Purpose Country','Purpose','Status','Action'],a.map(x=>`<tr><td><input type="checkbox" class="inquiry-select" value="${esc(x.id)}" aria-label="Select inquiry"></td><td>${value(x.ref||x.id)}</td><td>${value(x.name)}</td><td>${value(x.profession)}</td><td>${humanDate(x.date)}<small>${value(x.time)}</small></td><td>${value(x.phone)}<small>WhatsApp: ${value(x.whatsapp)}</small></td><td>${value(x.email)}</td><td>${value(x.country)}</td><td>${value(x.district)} / ${value(x.city)}</td><td>${value(x.service)}<small>${value(x.purposeCountry)}</small></td><td>${value(x.purpose)}</td><td>${tag(x.status)}</td><td>${x.status==='New'?`<button class="link-btn" data-action="inquiry-to-lead" data-id="${esc(x.id)}">Convert to Lead</button> &nbsp;`: '<span class="muted">Converted</span> &nbsp;'}<button class="link-btn" data-action="delete-inquiry" data-id="${esc(x.id)}">Delete</button></td></tr>`).join(''))}</div>`}

function leads(){const a=state.leads.filter(x=>x.status!=='Converted'&&match(x.name,x.email,x.phone,x.whatsapp,x.profession,x.country,x.district,x.city,x.reference,leadRef(x),x.service,x.temperature,x.status,x.source)&&(!leadListState.keyword||[x.name,x.email,x.phone,x.whatsapp,x.district,x.city,leadRef(x),x.service].some(v=>String(v||'').toLowerCase().includes(leadListState.keyword.toLowerCase()))));const pages=Math.max(1,Math.ceil(a.length/leadListState.size));leadListState.page=Math.min(leadListState.page,pages-1);const shown=a.slice(leadListState.page*leadListState.size,(leadListState.page+1)*leadListState.size);return head('Relationships','Leads','Track prospective clients, contact details, interest and follow-up.')+`<div class="lead-toolbar"><div class="tabs lead-tabs">${['All','Active'].map(c=>`<button class="tab ${filter===c?'active':''}" data-filter="${c}">${c} leads</button>`).join('')}</div><label class="lead-size-label" for="lead-size">Show entries <select id="lead-size">${[10,25,50,100,500,1000].map(n=>`<option ${leadListState.size===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="lead-toolbar-right"><span class="lead-total">Total: <strong>${a.length}</strong></span><label class="lead-search-label" for="lead-keyword">Search lead <input id="lead-keyword" value="${esc(leadListState.keyword)}" placeholder="Name, ID, email or city"></label><button class="btn primary" data-action="new-lead">${icon('plus')} New lead</button></div></div><div class="lead-pagination"><span>Page ${leadListState.page+1} of ${pages}</span><button class="btn small" data-action="lead-prev" ${leadListState.page===0?'disabled':''}>Previous</button><button class="btn small" data-action="lead-next" ${leadListState.page>=pages-1?'disabled':''}>Next</button><button class="btn small" data-action="print-list">Print list</button></div><div class="card lead-list-table">${table(['Lead ID','Full name','Profession','Date & time','Mobile / WhatsApp','Email','Country','District / City','Service / Purpose Country','Purpose','Status','Reference','Follow-up','Action'],shown.map(x=>{const source=state.inquiries.find(q=>q.id===x.sourceInquiryId);const inquiryDate=x.inquiryDate||source?.date,inquiryTime=x.inquiryTime||source?.time,purposeCountry=x.purposeCountry||source?.purposeCountry;return `<tr><td><button class="link-btn" data-action="lead-detail" data-id="${esc(x.id)}">${esc(leadRef(x))}</button></td><td><strong>${value(x.name)}</strong></td><td>${value(x.profession)}</td><td>${humanDate(inquiryDate)}<small>${value(inquiryTime)}</small></td><td>${value(x.phone)}<small>WhatsApp: ${value(x.whatsapp)}</small></td><td>${value(x.email)}</td><td>${value(x.country)}</td><td>${value(x.district)} / ${value(x.city)}</td><td>${value(x.service)}<small>${value(purposeCountry)}</small></td><td>${value(Array.isArray(x.purpose)?x.purpose.join(', '):x.purpose)}</td><td>${leadBadge(x.status,'stage')}<small>${leadBadge(x.temperature||'Not classified','interest')}</small></td><td>${x.reference?value(x.reference):''}${x.sourceInquiryRef||x.sourceInquiryId?`<span class="inquiry-ref">Website inquiry ID: ${value(x.sourceInquiryRef||x.sourceInquiryId)}</span>`:(!x.reference?'—':'')}</td><td>${humanDate(x.followup)}</td><td><button class="link-btn" data-action="lead-detail" data-id="${esc(x.id)}">View details</button><br><button class="link-btn" data-action="convert-lead" data-id="${esc(x.id)}">Convert to client →</button></td></tr>`}).join(''))}</div>`}

function clients(){
 const categories=['All','Bangladesh','NRB','Unclassified'];
 const matchesCase=(c,m)=>m.clientId===c.id&&(!clientFilters.country||m.country===clientFilters.country)&&(!clientFilters.service||m.category===clientFilters.service)&&(!clientFilters.purpose||(Array.isArray(m.purpose)?m.purpose:[m.purpose]).includes(clientFilters.purpose));
 const a=state.clients.filter(c=>{const word=clientFilters.keyword.trim().toLowerCase(),clientPurpose=Array.isArray(c.purpose)?c.purpose:[c.purpose],direct=!clientFilters.country&&(!clientFilters.service||c.service===clientFilters.service)&&(!clientFilters.purpose||clientPurpose.includes(clientFilters.purpose));return (filter==='All'||(c.segment||'Unclassified')===filter)&&match(c.name,c.email,c.country,c.segment,c.district,c.city,clientRef(c))&&(!clientFilters.city||`${c.city||''} ${c.district||''}`.toLowerCase().includes(clientFilters.city.toLowerCase()))&&(!word||[c.name,c.email,c.phone,c.mobile,c.whatsapp,c.country,c.district,c.city,clientRef(c),...clientPurpose,...state.matters.filter(m=>m.clientId===c.id).flatMap(m=>[m.country,...(Array.isArray(m.purpose)?m.purpose:[m.purpose])])].some(x=>String(x||'').toLowerCase().includes(word)))&&(!clientFilters.from||c.registrationDate&&c.registrationDate>=clientFilters.from)&&(!clientFilters.to||c.registrationDate&&c.registrationDate<=clientFilters.to)&&(!(clientFilters.country||clientFilters.service||clientFilters.purpose)||direct||state.matters.some(m=>matchesCase(c,m)))});
 const pages=Math.max(1,Math.ceil(a.length/clientFilters.size));clientFilters.page=Math.min(clientFilters.page,pages-1);const shown=a.slice(clientFilters.page*clientFilters.size,(clientFilters.page+1)*clientFilters.size);

 const amounts=c=>{const totals=clientCurrencyTotals(state,c.id);const entries=Object.entries(totals).filter(([currency])=>canSeeCurrency(currency));return entries.length?entries.map(([currency,t])=>`<div class="client-finance"><strong>${money(t.paid,currency)} paid</strong><small>${money(t.agreed,currency)} agreed · ${money(t.feeBalance,currency)} fee balance · ${money(t.scheduledBalance,currency)} scheduled</small></div>`).join(''):'<span class="muted">No case fees yet</span>'};
 return head('Relationships','Clients','Separate Bangladesh and overseas clients, with each currency shown independently.','','')+`<div class="compact-list-toolbar"><div class="tabs">${categories.map(c=>`<button class="tab ${filter===c?'active':''}" data-filter="${esc(c)}">${esc(c)} <span>(${c==='All'?state.clients.length:state.clients.filter(x=>(x.segment||'Unclassified')===c).length})</span></button>`).join('')}</div><div class="field compact-inline"><label>Show entries</label><select id="client-size">${[10,25,50,100,500,1000].map(v=>`<option value="${v}" ${clientFilters.size===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field compact-inline"><label>Total</label><div style="display:inline-flex;align-items:center;gap:5px;border:1px solid #d3d8dc;border-radius:3px;background:#f8f8f8;padding:4px 8px;width:max-content;font-size:12px">Total: <strong style="display:inline-flex;align-items:center;justify-content:center;background:#19a85b;color:white;border-radius:999px;min-width:19px;height:19px;padding:0 4px;font-size:11px">${a.length}</strong></div></div><button class="btn primary" data-action="new-client">${icon('plus')} Add client</button></div><div class="card compact-client-filters"><div class="form-grid"><div class="field"><label for="client-keyword">Search</label><input id="client-keyword" value="${esc(clientFilters.keyword)}" placeholder="ID, name, email, category, country, district, city"></div><div class="field"><label>Service</label><select id="client-service"><option value="">All services</option>${services.map(v=>`<option ${clientFilters.service===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Category / purpose</label><select id="client-purpose"><option value="">All categories</option>${[...new Set(clientFilters.service?(state.serviceCategories[clientFilters.service]||[]):Object.values(state.serviceCategories).flat())].map(v=>`<option ${clientFilters.purpose===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Registration from</label><input id="client-from" type="date" value="${esc(clientFilters.from)}" max="${esc(clientFilters.to)}"></div><div class="field"><label>Registration to</label><input id="client-to" type="date" value="${esc(clientFilters.to)}" min="${esc(clientFilters.from)}"></div></div><p>Page ${clientFilters.page+1} of ${pages} · ${a.length} matching clients</p><button class="btn small" data-action="client-prev" ${clientFilters.page===0?'disabled':''}>Previous</button> <button class="btn small" data-action="client-next" ${clientFilters.page>=pages-1?'disabled':''}>Next</button> <button class="btn small" data-action="print-list">Print list</button></div>`+`<div class="callout">Use the Bangladesh and NRB tabs to group clients by residence. Scheduled balances cover installments entered so far.</div><div class="card client-print-table">${table(['Client ID','Client name','Registration date','Phone','Mobile','WhatsApp','Email','Gender','Category','Country','District','City','Matters','Fee & payments by currency','Documents','Action'],shown.map(c=>`<tr><td><button class="link-btn" data-action="client-detail" data-id="${esc(c.id)}">${esc(clientRef(c))}</button></td><td><div style="display:flex;align-items:center;gap:8px">${c.demoImages?.clientPhoto?`<button type="button" data-action="client-photo" data-id="${esc(c.id)}" aria-label="View client photo" style="border:0;background:none;padding:0"><img src="${esc(c.demoImages.clientPhoto)}" alt="Client photo" style="width:36px;height:36px;border-radius:50%;object-fit:cover"></button>`:'<span class="team-avatar" aria-label="No photo">—</span>'}<strong>${value(c.name)}</strong></div></td><td>${humanDate(c.registrationDate)}</td><td>${value(c.phone)}</td><td>${value(c.mobile)}</td><td>${value(c.whatsapp)}</td><td>${value(c.email)}</td><td>${value(c.gender)}</td><td>${categoryLines([...new Set([...(Array.isArray(c.purpose)?c.purpose:[c.purpose]), ...state.matters.filter(m=>m.clientId===c.id).flatMap(m=>Array.isArray(m.purpose)?m.purpose:[m.purpose])].filter(Boolean))])}</td><td>${value(c.country)}</td><td>${value(c.district)}</td><td>${value(c.city)}</td><td>${state.matters.filter(m=>m.clientId===c.id).length}</td><td>${amounts(c)}</td><td>${c.driveUrl?'<span class="pill green">Link saved</span>':'<span class="pill gray">Not linked</span>'}</td><td><button class="link-btn" data-action="client-detail" data-id="${esc(c.id)}">View profile →</button></td></tr>`).join(''))}</div>`
}
function matters(){const cats=['All','Open','Upcoming deadlines','U.S. Immigration','Bangladesh Law','Global Visa'];const a=state.matters.filter(m=>(filter==='All'||(filter==='Open'?m.status!=='Closed':filter==='Upcoming deadlines'?dashboardAlertRecords('deadlines-upcoming').includes(m):m.category===filter))&&match(m.ref,m.title,m.category,client(m.clientId)?.name)&&(!caseListFilters.keyword.trim()||[m.ref,m.title,m.category,m.country,m.purpose,m.status,client(m.clientId)?.name,clientRef(client(m.clientId))].some(v=>String(v||'').toLowerCase().includes(caseListFilters.keyword.trim().toLowerCase())))&&(!caseListFilters.from||m.caseDate&&m.caseDate>=caseListFilters.from)&&(!caseListFilters.to||m.caseDate&&m.caseDate<=caseListFilters.to));return head('Legal work','Cases & Matters','Manage separate workflows for every practice area.')+`<div class="compact-list-toolbar case-toolbar"><div class="tabs">${cats.map(c=>`<button class="tab ${filter===c?'active':''}" data-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><label for="case-list-from">From <input id="case-list-from" type="date" value="${esc(caseListFilters.from)}" max="${esc(caseListFilters.to)}"></label><label for="case-list-to">To <input id="case-list-to" type="date" value="${esc(caseListFilters.to)}" min="${esc(caseListFilters.from)}"></label><span class="case-count">${a.length} matching · ${state.matters.length} total</span><label for="case-list-search">Search <input id="case-list-search" type="search" value="${esc(caseListFilters.keyword)}" placeholder="Client, case or category"></label><button class="btn primary" data-action="new-matter">${icon('plus')} New matter</button><button class="btn small" data-action="print-list">Print list</button></div><p class="case-filter-note"><small>Cases without a creation date are excluded when a date filter is selected.</small></p><div class="card case-list-table">${table(['Case / client','Practice area','Jurisdiction','Status','Assigned','Next date','Action'],a.map(m=>`<tr><td><strong><button class="link-btn" data-action="matter-detail" data-id="${esc(m.id)}">${value(m.ref)}</button> · ${value(m.title)}</strong><small>${client(m.clientId)?`<button class="link-btn" data-action="client-detail" data-id="${esc(m.clientId)}">${esc(clientRef(client(m.clientId)))}</button>`:"—"} · ${value(client(m.clientId)?.name)}</small></td><td>${value(m.category)}<small>${categoryLines(m.purpose)}</small></td><td>${value(m.country)}</td><td>${caseBadge(m.status)}</td><td>${value(m.assigned)}</td><td>${humanDate(m.nextDate)}</td><td><button class="link-btn" data-action="matter-detail" data-id="${esc(m.id)}">Open →</button></td></tr>`).join(''))}</div>`}
function tasks(){const a=[...state.tasks].filter(x=>(filter==='Upcoming appointments'?dashboardAlertRecords('appointments-upcoming').includes(x):filter!=='Open'||!x.done)&&match(x.title,x.related,x.assigned)).sort((a,b)=>Number(a.done)-Number(b.done)||a.dueDate.localeCompare(b.dueDate));return head('Your priorities','Tasks & Reminders','Keep follow-ups and key dates visible to the team.','new-task','Add To-Do')+`<div class="tabs">${['All','Open','Upcoming appointments'].map(c=>`<button class="tab ${filter===c?'active':''}" data-filter="${c}">${c==='Upcoming appointments'?'Upcoming appointments · next 30 days':c+' Tasks &amp; Reminders'}</button>`).join('')}</div><div class="callout">Dates shown here are manually entered. Automatic email or phone notifications will require a connected notification service.</div><div class="card task-list-table">${table(['Task / type','Related to','Assigned to','Due date / time','Note','Status','Action'],a.map(t=>`<tr><td><strong>${value(t.title)}</strong><small>${value(t.taskType)}</small></td><td>${value(t.related)}</td><td>${value(t.assigned)}</td><td>${humanDate(t.dueDate)}<small>${value(t.dueTime)}</small></td><td>${value(t.note)}</td><td>${taskBadge(t.done?'Completed':t.dueDate<today()?'Overdue':'Open')}</td><td><button class="link-btn" data-action="toggle-task" data-id="${esc(t.id)}">${t.done?'Reopen':'Mark complete'}</button></td></tr>`).join(''))}</div>`}
let transactionFrom='',transactionTo='',transactionType='All';
function billing(){
 const permitted=m=>m&&canSeeCurrency(m.currency)&&(filter==='All'||(filter==='Other'?!['USD','BDT'].includes(m.currency):m.currency===filter));
 const totals=Object.entries(totalsByCurrency(state)).filter(([c])=>canSeeCurrency(c)&&(filter==='All'||(filter==='Other'?!['USD','BDT'].includes(c):c===filter)));
 const installments=state.installments.filter(i=>permitted(matter(i.matterId))&&match(matter(i.matterId)?.ref,client(matter(i.matterId)?.clientId)?.name,i.label));
 const payments=state.payments.filter(p=>permitted(matter(p.matterId))&&match(client(matter(p.matterId)?.clientId)?.name,matter(p.matterId)?.ref,p.status));
 const refunds=state.refunds.filter(r=>permitted(matter(r.matterId))&&match(client(matter(r.matterId)?.clientId)?.name,matter(r.matterId)?.ref,r.status));
 const events=(state.paymentEvents||[]).filter(e=>permitted(matter(e.matterId))).slice().reverse();
 const pending=payments.filter(p=>p.status==='Pending').length;
 const transactions=[...payments.filter(p=>p.status==='Approved').map(p=>({date:p.date,type:'Client receipt',matterId:p.matterId,method:p.method,amount:p.amount})),...refunds.filter(r=>r.status==='Approved').map(r=>({date:r.date,type:'Refund',matterId:r.matterId,method:r.method,amount:r.amount}))].filter(x=>(!transactionFrom||x.date>=transactionFrom)&&(!transactionTo||x.date<=transactionTo)&&(transactionType==='All'||x.type===transactionType)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
 const transactionTotals={};for(const t of transactions){const currency=matter(t.matterId)?.currency;if(!currency)continue;transactionTotals[currency]??={receipts:0,refunds:0};transactionTotals[currency][t.type==='Refund'?'refunds':'receipts']+=t.amount;}

 return head('Finance','Billing & Payments','Separate accounts by currency and track every approved payment.','new-installment','Add installment')+`<div class="tabs">${['All','USD','BDT','Other'].map(c=>`<button class="tab ${filter===c?'active':''}" data-filter="${c}">${c==='All'?'All permitted accounts':c==='USD'?'USD account':c==='BDT'?'BDT account':'Other currencies'}</button>`).join('')}</div><div class="callout">Demo permissions and edit history are illustrative and stored only in this browser. Actual account access, audit security and team logins are not connected.</div><div class="details-grid">${totals.map(([c,t])=>`<div class="card detail-box"><span>${esc(c)} · scheduled installments</span><strong class="money">${money(t.scheduled,c)}</strong><p class="task-detail">${money(t.paid,c)} approved · ${money(t.balance,c)} scheduled balance</p></div>`).join('')}<div class="card detail-box"><span>Approval queue · visible accounts</span><strong>${pending} pending</strong><p class="task-detail">Only the demo admin can approve payments</p></div></div><div style="height:17px"></div><section class="card" data-billing-section="installments"><div class="card-head"><div><h2 class="billing-section-title">Installment schedule</h2><p>Balances exclude payments awaiting approval.</p></div><button class="btn small" data-action="new-payment">${icon('plus')} Record payment</button></div>${table(['Matter / client','Installment','Due','Amount','Approved','Balance','Status'],installments.map(i=>{const m=matter(i.matterId);return `<tr><td><strong>${value(m.ref)}</strong><small>${value(client(m.clientId)?.name)}</small></td><td>${value(i.label)}</td><td>${humanDate(i.dueDate)}</td><td class="money">${money(i.amount,m.currency)}</td><td class="money">${money(paidFor(state,i.id),m.currency)}</td><td class="money">${money(remainingFor(state,i),m.currency)}</td><td>${tag(installmentStatus(state,i))}</td></tr>`}).join(''))}</section><div style="height:17px"></div><section class="card" data-billing-section="payments"><div class="card-head"><div><h2 class="billing-section-title">Payment activity</h2><p>Submitted entries are locked; admin grants any edit permission.</p></div></div>${table(['Case / client','Installment','Payment date','Partial / full','Mode of payment','Amount','Status','Action'],payments.map(p=>{const m=matter(p.matterId), i=state.installments.find(x=>x.id===p.installmentId);return `<tr><td><strong>${value(m.ref)}</strong><small>${value(client(m.clientId)?.name)}</small></td><td>${value(i?.label)}</td><td>${humanDate(p.date)}</td><td>${value(p.coverage||'Not specified')}</td><td>${value(p.method)}${p.method==='Cheque'&&p.chequeImage?`<br><button class="link-btn" data-action="view-cheque" data-id="${esc(p.id)}">View cheque image</button>`:''}</td><td>${money(p.amount,m.currency)}</td><td>${tag(p.status)}</td><td>${p.status==='Pending'&&isAdmin()?`<button class="link-btn" data-action="approve-payment" data-id="${esc(p.id)}">Approve</button> &nbsp; <button class="mini-btn danger" data-action="reject-payment" data-id="${esc(p.id)}">Reject</button> &nbsp;`:''}${p.status!=='Rejected'&&canEditCurrency(m.currency)?`<button class="link-btn" data-action="edit-payment" data-id="${esc(p.id)}">Edit amount</button> `:''}${p.status!=='Rejected'&&canEditDetails(m.currency)?`<button class="link-btn" data-action="edit-payment-details" data-id="${esc(p.id)}">Edit details</button>`:''}${p.status==='Rejected'||(!canEditCurrency(m.currency)&&!canEditDetails(m.currency))?'<span class="muted">Entry locked</span>':''}</td></tr>`}).join(''))}</section><div style="height:17px"></div><section class="card" data-billing-section="refunds"><div class="card-head"><div><h2 class="billing-section-title">Refund report</h2><p>Recording a refund does not transfer money. Approved refunds adjust the account balance.</p></div><button class="btn small" data-action="new-refund">${icon('plus')} Record refund</button></div>${table(['Case / client','Refund date','Method','Amount','Reason','Status','Action'],refunds.map(r=>{const m=matter(r.matterId);return `<tr><td><strong>${value(m.ref)}</strong><small>${value(client(m.clientId)?.name)}</small></td><td>${humanDate(r.date)}</td><td>${value(r.method)}</td><td>${money(r.amount,m.currency)}</td><td>${value(r.reason)}</td><td>${tag(r.status)}</td><td>${r.status==='Pending'&&isAdmin()?`<button class="link-btn" data-action="approve-refund" data-id="${esc(r.id)}">Approve</button>`:'—'}</td></tr>`}).join(''))}</section><div style="height:17px"></div><section class="card transaction-report" data-billing-section="transactions"><div class="card-head"><div><h2 class="billing-section-title">Transaction report</h2><p>Approved client receipts and refunds only · browser demo · amounts are not classified as income</p></div><div><button class="btn small" data-action="add-transaction-demo">Add sample BDT transactions</button> <button class="btn small" data-action="print-transaction">Print / save PDF</button></div></div><div class="transaction-filters"><div class="field"><label for="transaction-from">From date</label><input type="date" id="transaction-from" value="${esc(transactionFrom)}"></div><div class="field"><label for="transaction-to">To date</label><input type="date" id="transaction-to" value="${esc(transactionTo)}"></div><div class="field"><label for="transaction-type">Transaction type</label><select id="transaction-type">${['All','Client receipt','Refund'].map(v=>`<option ${transactionType===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="card-body">${Object.entries(transactionTotals).map(([c,t])=>`<p><strong>${esc(c)}</strong> · Receipts ${money(t.receipts,c)} · Refunds ${money(t.refunds,c)} · Net ${money(t.receipts-t.refunds,c)}</p>`).join('')||'<p>No approved transactions match these filters.</p>'}</div>${table(['Date','Transaction','Client / case','Method','Amount','Currency'],transactions.map(x=>{const m=matter(x.matterId);return `<tr><td>${humanDate(x.date)}</td><td>${esc(x.type)}</td><td>${value(client(m?.clientId)?.name)} · ${value(m?.ref)}</td><td>${value(x.method)}</td><td>${money(x.amount,m?.currency)}</td><td>${value(m?.currency)}</td></tr>`}).join(''))}</section><div style="height:17px"></div><section class="card" data-billing-section="history"><div class="card-head"><div><h2 class="billing-section-title">Payment edit history</h2><p>Previous and updated values, the person, and date/time in Chicago.</p></div></div>${table(['Case','Field changed','Previous value','New value','Changed by','Date and time'],events.map(e=>`<tr><td><strong>${value(matter(e.matterId)?.ref)}</strong></td><td>${value(e.field||'Amount')}</td><td>${e.field==='Amount'||!e.field?money(e.oldAmount,e.currency):value(e.oldValue)}</td><td>${e.field==='Amount'||!e.field?money(e.newAmount,e.currency):value(e.newValue)}</td><td>${value(e.actorName)}</td><td>${esc(timeInChicago(e.changedAt))}</td></tr>`).join(''))}</section>`
}
document.addEventListener('change',e=>{if(['transaction-from','transaction-to','transaction-type'].includes(e.target.id)){transactionFrom=document.getElementById('transaction-from').value;transactionTo=document.getElementById('transaction-to').value;transactionType=document.getElementById('transaction-type').value;renderView();}});
function invoiceSummary(inv){const m=matter(inv.matterId);const related=state.payments.filter(p=>p.matterId===inv.matterId&&p.status==='Approved');const gross=related.reduce((n,p)=>n+p.amount,0);const refunded=related.reduce((n,p)=>n+refundedForPayment(state,p.id),0);const paid=gross-refunded,total=inv.professionalFee+inv.governmentFee;return {m,paid,gross,refunded,total,balance:total-paid,status:invoiceStatus(total,paid,refunded)};}
function invoices(){
 const rows=state.invoices.filter(i=>{const m=matter(i.matterId);return m&&canSeeCurrency(m.currency)&&match(i.number,m.ref,client(m.clientId)?.name)});
 const changes=state.invoiceChanges.filter(r=>canSeeCurrency(r.currency)).slice().reverse();
 return head('Finance','Invoices','Create a simple invoice and review proposed fee changes.','new-invoice','Create invoice')+`<div class="callout">Sample data only. Invoice changes take effect only after demo admin approval. The demo does not send invoices, process payments, or enforce real access controls.</div><div class="card">${table(['Invoice','Client / case','Issued','Due','Total','Net approved paid','Fee balance','Status','Action'],rows.map(i=>{const {m,paid,total,balance,status}=invoiceSummary(i);return `<tr><td><strong>${value(i.number)}</strong><small>Demo invoice</small></td><td><strong>${value(client(m.clientId)?.name)}</strong><small>${value(m.ref)}</small></td><td>${humanDate(i.issueDate)}</td><td>${humanDate(i.dueDate)}</td><td>${money(total,m.currency)}</td><td>${money(paid,m.currency)}</td><td>${money(balance,m.currency)}</td><td>${tag(status)}</td><td><button class="link-btn" data-action="invoice-preview" data-id="${esc(i.id)}">View / print →</button>${isAdmin()||(actor()?.permissions||[]).includes('Request invoice changes')?`<br><button class="link-btn" data-action="request-invoice-change" data-id="${esc(i.id)}">Request fee change</button>`:''}</td></tr>`}).join(''))}</div><div style="height:17px"></div><section class="card"><div class="card-head"><div><h2>Invoice change requests &amp; history</h2><p>Original and proposed amounts, reason, requester and admin decision.</p></div></div>${table(['Invoice / case','Original total','Proposed total','Reason','Requested by / time','Status / reviewer','Action'],changes.map(r=>{const inv=state.invoices.find(i=>i.id===r.invoiceId);return `<tr><td><strong>${value(inv?.number)}</strong><small>${value(matter(r.matterId)?.ref)}</small></td><td>${money(r.beforeProfessional+r.beforeGovernment,r.currency)}</td><td>${money(r.afterProfessional+r.afterGovernment,r.currency)}</td><td>${value(r.reason)}</td><td>${value(r.requestedBy)}<small>${esc(timeInChicago(r.requestedAt))}</small></td><td>${tag(r.status)}${r.reviewedBy?`<small>${value(r.reviewedBy)} · ${esc(timeInChicago(r.reviewedAt))}</small>`:''}</td><td>${r.status==='Pending'&&isAdmin()?`<button class="link-btn" data-action="approve-invoice-change" data-id="${esc(r.id)}">Approve</button> &nbsp; <button class="mini-btn danger" data-action="reject-invoice-change" data-id="${esc(r.id)}">Reject</button>`:'—'}</td></tr>`}).join(''))}</section>`
}
function documents(){const a=state.documentRequests.filter(r=>match(client(r.clientId)?.name,clientRef(client(r.clientId)),r.subject,r.subfolder));return head('Client documents','Document Requests','Prepare client-specific requests and see where files should be organized.','new-document-request','New request')+`<div class="callout">This demo prepares a request only; no email is sent, no upload link is active, and Google Drive is not connected.</div><div class="card">${table(['Client / ID','Email subject','Subfolder','Created','Status','Action'],a.map(r=>{const c=client(r.clientId);return `<tr><td><strong>${value(c?.name)}</strong><small>${esc(clientRef(c))}</small></td><td>${value(r.subject)} · ${esc(clientRef(c))}</td><td>${value(r.subfolder||'Client folder')}</td><td>${humanDate(r.date)}</td><td>${tag('Draft')}</td><td><button class="link-btn" data-action="document-preview" data-id="${esc(r.id)}">Preview email →</button></td></tr>`}).join(''))}</div><div style="height:17px"></div><div class="integration-grid"><div class="card service-card"><div class="icon-box">${icon('folder')}</div><h3>Client-specific folder</h3><p>When connected, each request will be directed to the selected client's own Google Drive folder, with a chosen or newly created subfolder.</p></div><div class="card service-card"><div class="icon-box gold">${icon('shield')}</div><h3>Client upload link</h3><p>The intended live upload flow will use a client-specific link and will require Google Drive and email configuration before it can send or receive documents.</p></div></div>`}
function communications(){return head('Conversations','Communication Inbox','Bring conversations and client records together in one place.')+`<div class="integration-grid"><section class="card integration"><div class="int-icon">WA</div><div><h3>WhatsApp Business</h3><p>Link your business number to receive and respond to client messages.</p>${tag('Not connected')} <span class="muted">Meta setup required</span></div></section><section class="card integration"><div class="int-icon messenger">M</div><div><h3>Facebook Messenger</h3><p>Connect your Facebook Business Page to manage Page conversations.</p>${tag('Not connected')} <span class="muted">Page permissions required</span></div></section></div><div class="callout">Sample conversations illustrate the proposed workflow. No messages are received or sent in this demo.</div><section class="card"><div class="card-head"><div><h2>Conversation examples</h2><p>Connect a channel and associate messages with a lead or client in the live version.</p></div></div>${table(['Contact','Channel','Latest message','Date','CRM status'],state.messages.filter(x=>match(x.name,x.channel,x.body)).map(x=>`<tr><td><strong>${value(x.name)}</strong></td><td>${value(x.channel)}</td><td>${value(x.body)}</td><td>${humanDate(x.date)}</td><td>${tag(x.status)}</td></tr>`).join(''))}</section>`}
function team(){if(!isAdmin())return head('Administration','Team & access','Admin controls team permissions.')+'<div class="callout">Only the demo admin can manage access.</div>';return head('Administration','Team & access','Plan access by role and by person.','new-team','Add team member')+`<div class="callout">These are demo controls only. Real sign-in, role restrictions and Drive permissions must be configured and tested before the team uses the CRM.</div><div class="card">${table(['Team member','Role','Example permissions','Status','Action'],state.team.filter(x=>match(x.name,x.email,x.role)).map((u,i)=>`<tr><td><div class="team-name"><div class="team-avatar">${esc(u.name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase())}</div><div><strong>${value(u.name)}</strong><small>${value(u.email)}</small></div></div></td><td>${value(u.role)}</td><td><div class="permission-chips">${u.permissions.map(p=>`<span>${esc(p)}</span>`).join('')}</div></td><td>${tag(u.status)}</td><td>${u.id===state.team[0]?.id?'Owner':`<buttonclass="link-btn" data-action="team-edit" data-id="${esc(u.id)}">Manage access</button>`}</td></tr>`).join(''))}</div>`}
function settings(){return head('Administration','Workspace settings','A starting point for your firm’s working environment.')+`<div class="integration-grid">${isAdmin()?`<div class="card service-card"><div class="icon-box gold">${icon('shield')}</div><h3>Access &amp; Permissions</h3><strong>Financial information visibility</strong><p>Demo setting for this browser only. Some screens are not yet covered; this is not secure access control.</p><button class="btn small" data-action="toggle-demo-finance-visibility">${state.hideTeamFinance?'Show demo finance to team':'Hide demo finance from team'}</button><p>Current demo setting: ${state.hideTeamFinance?'Hidden on supported screens':'Visible according to demo permissions'}</p></div>`:''}<div class="card service-card"><div class="icon-box gold">${icon('shield')}</div><h3>Firm administration</h3><p>M. R. I. Chowdhury &amp; Associates<br>Primary workspace: U.S. &amp; Bangladesh<br>Default time zone: America / Chicago</p></div><div class="card service-card"><div class="icon-box">${icon('folder')}</div><h3>Document connection</h3><p>Client Drive folder links can be previewed in profiles. A shared Drive and file-level permissions have not been connected.</p></div><div class="card service-card"><div class="icon-box green">${icon('bell')}</div><h3>Notifications</h3><p>Tasks and due dates appear in the demo. Email, WhatsApp and other automatic alerts require a connected service.</p></div><div class="card service-card"><div class="icon-box rose">${icon('settings')}</div><h3>Demo data &amp; source</h3><p>Changes are saved only in this browser. You can reset the fictional examples or download the demo source files.</p><div style="margin-top:13px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn small" data-action="reset-demo">Reset demo</button><a class="btn small" href="./firm-crm-demo-source.zip" download>Download demo source</a></div></div></div>`}
// Dashboard alerts use the same records for both the count and the detail list.
function dashboardAlertRecords(kind){
 const d=today();
 if(kind==='follow-today'||kind==='follow-overdue') return state.matters.filter(m=>m.status!=='Closed'&&!m.followupDone&&m.nextDate&&(kind==='follow-today'?m.nextDate===d:m.nextDate<d));
 if(kind==='payment-today'||kind==='payment-overdue') return state.installments.filter(i=>{const m=matter(i.matterId);return m&&canSeeCurrency(m.currency)&&remainingFor(state,i)>0&&i.dueDate&&(kind==='payment-today'?i.dueDate===d:i.dueDate<d)});
 if(kind==='tasks-open') return state.tasks.filter(t=>!t.done);
 if(kind==='deadlines-upcoming') return state.matters.filter(m=>m.status!=='Closed'&&m.deadlineDate>=d&&m.deadlineDate<=plusDays(d,30));
 if(kind==='appointments-upcoming') return state.tasks.filter(t=>!t.done&&t.taskType==='Meeting'&&t.dueDate>=d&&t.dueDate<=plusDays(d,30));
 if(kind==='payment-pending') return state.payments.filter(p=>p.status==='Pending'&&canSeeCurrency(matter(p.matterId)?.currency));
 return [];
}
function dashboardAlerts(){const cards=[['follow-today','Follow-ups due today','<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M9 15l2 2 4-4"/>'],['follow-overdue','Overdue follow-ups','<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2M18 4l2 2"/>'],['tasks-open','Tasks & reminders','<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4.5h6M8 10l1 1 2-2M13 10h3M8 15l1 1 2-2M13 15h3"/>'],['deadlines-upcoming','Upcoming deadlines · next 30 days','<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>'],['appointments-upcoming','Upcoming appointments · next 30 days','<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'],['payment-today','Payments due today','<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>'],['payment-overdue','Overdue payments','<path d="M12 3 22 20H2L12 3zM12 9v5M12 17h.01"/>'],['payment-pending','Payments awaiting review','<path d="M4 5h11v14H4zM7 9h5M7 13h4"/><circle cx="16.5" cy="15.5" r="3.5"/><path d="m19 18 2 2"/>']];return `<section class="card alert-section"><div class="card-head"><div><h2>Today &amp; Attention</h2><p>Demo records in this browser · select a card for matching items</p></div><button class="btn small" data-action="add-followup-demo">Add sample follow-ups</button></div><div class="stats alert-grid">${cards.map(([key,label,svg])=>`<button type="button" class="card stat stat-link alert-card" data-alert="${key}"><div class="stat-top"><span>${label}</span><span class="icon-box"><svg viewBox="0 0 24 24" aria-hidden="true">${svg}</svg></span></div><div class="stat-value">${dashboardAlertRecords(key).length}</div><div class="stat-note">View matching records →</div></button>`).join('')}</div></section>`}
document.addEventListener('click',e=>{const button=e.target.closest('[data-alert]');if(!button)return;const kind=button.dataset.alert, records=dashboardAlertRecords(kind);const isFollow=kind.startsWith('follow-'), isTask=kind==='tasks-open'||kind==='appointments-upcoming', isDeadline=kind==='deadlines-upcoming', isPending=kind==='payment-pending';let rows=records.map(item=>{if(isFollow){const c=client(item.clientId);return `<tr><td>${value(c?.name)}</td><td>${value(item.ref)}</td><td>${humanDate(item.nextDate)}</td><td><button class="link-btn" data-action="matter-detail" data-id="${esc(item.id)}">View case</button></td></tr>`}if(isDeadline)return `<tr><td>${value(client(item.clientId)?.name)}</td><td>${value(item.ref)}</td><td>${humanDate(item.deadlineDate)}</td><td><button class="link-btn" data-action="matter-detail" data-id="${esc(item.id)}">View case</button></td></tr>`;if(isTask)return `<tr><td>${value(item.title)}</td><td>${value(item.assigned)}</td><td>${humanDate(item.dueDate)}</td><td>${item.dueDate&&item.dueDate<today()?'Overdue':'Open'}</td></tr>`;const m=matter(item.matterId),c=client(m?.clientId);return `<tr><td>${value(c?.name)}</td><td>${value(m?.ref)}</td><td>${isPending?humanDate(item.date):humanDate(item.dueDate)}</td><td>${money(isPending?item.amount:remainingFor(state,item),m?.currency)}</td></tr>`}).join('');modal(button.querySelector('.stat-top span').textContent,`<p class="task-detail">${records.length} matching record(s). ${isPending?'Pending payments do not reduce the balance.':''}</p>${table(isTask?['Task','Assigned to','Due date','Status']:isFollow?['Client','Case','Follow-up date','Action']:isDeadline?['Client','Case','Deadline','Action']:['Client','Case',isPending?'Payment date':'Due date','Amount'],rows)}<div class="modal-actions"><button class="btn" data-page="${isTask?'tasks':isFollow||isDeadline?'matters':'billing'}" data-filter="${kind==='appointments-upcoming'?'Upcoming appointments':kind==='deadlines-upcoming'?'Upcoming deadlines':kind==='tasks-open'?'Open':'All'}">Open ${isTask?'tasks':isFollow||isDeadline?'cases':'billing'}</button></div>`);});
let reportFrom='',reportTo='';
function reports(){const within=d=>!!d&&(!reportFrom||d>=reportFrom)&&(!reportTo||d<=reportTo);const clients=state.clients.filter(c=>within(c.registrationDate));const fs=state.matters.filter(m=>m.nextDate&&within(m.nextDate));const tasks=state.tasks.filter(t=>within(t.dueDate));const installments=state.installments.filter(i=>within(i.dueDate)&&canSeeCurrency(matter(i.matterId)?.currency));const todayDate=today();const totals=totalsByCurrency(state);return head('Management','Reports','Review sample client, follow-up, task and payment information.')+`<div class="callout">Browser-only demo. Date filters apply to registration, follow-up, task and installment due dates. Financial totals below cover all dates and approved payments only.</div><div class="card card-body" style="padding:16px;margin-bottom:16px"><div class="form-grid"><div class="field"><label for="report-from">From</label><input id="report-from" type="date" value="${esc(reportFrom)}"></div><div class="field"><label for="report-to">To</label><input id="report-to" type="date" value="${esc(reportTo)}"></div></div><button class="btn small" data-action="print-list">Print / save PDF</button> <button class="btn small" data-action="export-reports">Export CSV for Excel</button></div><div class="stats">${stat('users','Clients registered',clients.length,'Within selected dates','','report-clients')}${stat('clock','Follow-ups due today',fs.filter(m=>!m.followupDone&&m.status!=='Closed'&&m.nextDate===todayDate).length,'Within selected dates','','report-follow-today')}${stat('clock','Overdue follow-ups',fs.filter(m=>!m.followupDone&&m.status!=='Closed'&&m.nextDate<todayDate).length,'Within selected dates','','report-follow-overdue')}${stat('clock','Open tasks',tasks.filter(t=>!t.done).length,'Within selected dates','','report-tasks')}${stat('clock','Tasks due today',tasks.filter(t=>!t.done&&t.dueDate===todayDate).length,'Within selected dates','','report-tasks-today')}${stat('clock','Overdue tasks',tasks.filter(t=>!t.done&&t.dueDate<todayDate).length,'Within selected dates','','report-tasks-overdue')}</div><section class="card" style="margin-bottom:16px"><div class="card-head"><div><h2>Case follow-ups</h2><p>Filtered by follow-up date</p></div></div>${table(['Client','Case','Date','Assigned','Status'],fs.map(m=>`<tr><td>${value(client(m.clientId)?.name)}</td><td>${value(m.ref)}</td><td>${humanDate(m.nextDate)}</td><td>${value(m.assigned)}</td><td>${tag(m.followupDone?'Completed':m.status==='Closed'?'Case closed':m.nextDate<todayDate?'Overdue':m.nextDate===todayDate?'Due today':'Upcoming')}</td></tr>`).join(''))}</section><section class="card" style="margin-bottom:16px"><div class="card-head"><div><h2>Installments</h2><p>Filtered by due date; pending payments do not reduce balances</p></div></div>${table(['Client / case','Due date','Balance','Status'],installments.map(i=>{const m=matter(i.matterId);return `<tr><td>${value(client(m?.clientId)?.name)} · ${value(m?.ref)}</td><td>${humanDate(i.dueDate)}</td><td>${money(remainingFor(state,i),m?.currency)}</td><td>${tag(remainingFor(state,i)>0&&i.dueDate===todayDate?'Due today':installmentStatus(state,i))}</td></tr>`}).join(''))}</section><section class="card" style="margin-bottom:16px"><div class="card-head"><div><h2>Tasks &amp; reminders</h2><p>Filtered by due date</p></div></div>${table(['Task','Related to','Assigned','Due','Status'],tasks.map(t=>`<tr><td>${value(t.title)}</td><td>${value(t.related)}</td><td>${value(t.assigned)}</td><td>${humanDate(t.dueDate)}</td><td>${tag(t.done?'Completed':t.dueDate<todayDate?'Overdue':t.dueDate===todayDate?'Due today':'Upcoming')}</td></tr>`).join(''))}</section><section class="card" data-finance-section="payment-review" style="margin-bottom:16px"><div class="card-head"><div><h2>Payment review</h2><p>Filtered by payment date · demonstration only</p></div></div>${table(['Client / case','Date','Amount','Method','Status'],state.payments.filter(p=>within(p.date)&&canSeeCurrency(matter(p.matterId)?.currency)).map(p=>{const m=matter(p.matterId);return `<tr><td>${value(client(m?.clientId)?.name)} · ${value(m?.ref)}</td><td>${humanDate(p.date)}</td><td>${money(p.amount,m?.currency)}</td><td>${value(p.method)}</td><td>${tag(p.status)}</td></tr>`}).join(''))}</section><section class="card" data-finance-section="client-fee-balance" style="margin-bottom:16px"><div class="card-head"><div><h2>Client fee balances</h2><p>All dates · approved payments only · each currency shown separately</p></div></div>${table(['Client','Currency','Agreed fee','Approved paid','Fee balance','Action'],state.clients.flatMap(c=>Object.entries(clientCurrencyTotals(state,c.id)).filter(([currency])=>canSeeCurrency(currency)).map(([currency,t])=>`<tr><td>${value(c.name)}</td><td>${esc(currency)}</td><td>${money(t.agreed,currency)}</td><td>${money(t.paid,currency)}</td><td>${money(t.feeBalance,currency)}</td><td><button class="link-btn" data-action="client-detail" data-id="${esc(c.id)}">View profile</button></td></tr>`)).join(''))}</section><section class="card"><div class="card-head"><div><h2>Financial snapshot by currency</h2><p>All dates · scheduled installments</p></div></div><div class="card-body">${Object.entries(totals).filter(([currency])=>canSeeCurrency(currency)).map(([currency,t])=>`<p><strong>${esc(currency)}</strong> · Scheduled ${money(t.scheduled,currency)} · Approved ${money(t.paid,currency)} · Outstanding ${money(t.balance,currency)}</p>`).join('')||'<p>No permitted installment data.</p>'}</div></section>`;}
