document.addEventListener('change',e=>{const id=e.target.id;if(id!=='case-list-from'&&id!=='case-list-to')return;const val=e.target.value;if((id==='case-list-from'&&val&&caseListFilters.to&&val>caseListFilters.to)||(id==='case-list-to'&&val&&caseListFilters.from&&val<caseListFilters.from)){toast('From date must not be after To date.');renderView();return;}caseListFilters[id==='case-list-from'?'from':'to']=val;renderView();});


function calendarEvents(){return [{date:today(),type:'Lead follow-up',name:'Demo Lead',ref:'DEMO-LEAD',note:'Sample: call to discuss requested service.',status:'New',assigned:'Demo team',id:'calendar-demo-lead',source:'Demo example'}, {date:today(),type:'Case deadline',name:'Demo Client',ref:'DEMO-CASE',note:'Sample: review case documents before the deadline.',status:'In progress',assigned:'Demo team',id:'calendar-demo-case',source:'Demo example'}, ...state.leads.filter(l=>l.followup&&l.status!=='Converted').map(l=>({date:l.followup,type:'Lead follow-up',name:l.name,ref:leadRef(l),note:l.followupNote||l.note||l.notes||'',status:l.status||'',assigned:l.assigned||'',time:l.followupTime||'',id:l.id})),...state.matters.flatMap(m=>[{date:m.deadlineDate,type:'Case deadline',note:m.deadlineNote||''},{date:m.nextDate,type:'Case follow-up',note:m.caseNote||''}].filter(e=>e.date).map(e=>({...e,name:client(m.clientId)?.name||'',personId:client(m.clientId)?clientRef(client(m.clientId)):'',caseRef:m.ref,ref:m.ref,status:m.status||'',assigned:m.assigned||'',id:m.id}))),...state.tasks.filter(t=>t.dueDate).map(t=>({date:t.dueDate,type:t.taskType||'To-Do',name:(t.relatedType==='lead'?state.leads.find(l=>l.id===t.relatedId):client(t.relatedId))?.name||'',personId:t.relatedType==='lead'?(state.leads.find(l=>l.id===t.relatedId)?leadRef(state.leads.find(l=>l.id===t.relatedId)):''):(client(t.relatedId)?clientRef(client(t.relatedId)):''),title:t.title,caseRef:t.caseRef||'',ref:t.related||'',note:t.note||'',status:t.done?'Completed':'Open',assigned:t.assigned||'',time:t.dueTime||'',id:t.id,source:'To-Do'}))];}
function dashboardCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),events=calendarEvents();let cells=Array(first).fill('<div class="calendar-day empty-day"></div>');for(let d=1;d<=days;d++){const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,items=events.filter(e=>e.date===iso);cells.push(`<div class="calendar-day ${iso===calendarSelected?'calendar-selected':''}"><strong>${d}</strong>${items.map(e=>`<button class="calendar-event ${e.type==='Lead follow-up'?'event-lead':e.type==='Case deadline'?'event-deadline':'event-case'}" data-calendar-type="${esc(e.type)}" data-calendar-id="${esc(e.id)}" data-calendar-date="${esc(e.date)}">${esc(e.name||e.ref||"Unassigned")} · ${esc(e.type)}${e.title?` · ${esc(e.title)}`:""}</button>`).join('')}</div>`)}return `<section class="card calendar-card"><div class="card-head"><h2>Calendar</h2><div><button class="btn small" data-calendar-nav="-1" aria-label="Previous month">‹</button> <button class="btn small" data-calendar-nav="today">Today</button> <label for="calendar-date" class="calendar-date-label">Select date</label> <input id="calendar-date" type="date" value="${esc(calendarSelected)}" aria-label="Select calendar date"> <button class="btn small" data-calendar-nav="1" aria-label="Next month">›</button></div></div><div class="calendar-month">${esc(calendarMonth.toLocaleString('en-US',{month:'long',year:'numeric'}))}</div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells.join('')}</div><p class="task-detail">Sample follow-ups and deadlines saved in this browser.</p></section>`;}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-calendar-nav]');if(nav){const v=nav.dataset.calendarNav;if(v==='today'){const n=new Date();calendarSelected=today();calendarMonth=new Date(n.getFullYear(),n.getMonth(),1)}else calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+Number(v),1);renderView();return}const button=e.target.closest('[data-calendar-type]');if(!button)return;const item=calendarEvents().find(x=>x.type===button.dataset.calendarType&&x.id===button.dataset.calendarId&&x.date===button.dataset.calendarDate);if(!item)return;modal(item.type,`<div class="detail-list"><div><span>Lead / Client Name</span><strong>${value(item.name)}</strong></div><div><span>Lead / Client ID</span><strong>${value(item.personId||(item.type==='Lead follow-up'?item.ref:''))}</strong></div><div><span>Case Reference</span><strong>${value(item.caseRef||(item.type==='Case deadline'||item.type==='Case follow-up'?item.ref:''))}</strong></div>${item.title?`<div><span>Task Title</span><strong>${value(item.title)}</strong></div>`:''}<div><span>Assigned to</span><strong>${value(item.assigned)}</strong></div><div><span>Status</span><strong>${value(item.status)}</strong></div><div><span>Note</span><strong>${value(item.note)}</strong></div><div><span>Source</span><strong>${value(item.source||(item.type==='Lead follow-up'?'Lead follow-up':'Case entry'))}</strong></div><div><span>Date</span><strong>${humanDate(item.date)}</strong></div><div><span>Time</span><strong>${value(item.time)}</strong></div></div>`);});

document.addEventListener('change',e=>{if(e.target.id!=='calendar-date'||!e.target.value)return;calendarSelected=e.target.value;const [y,m]=calendarSelected.split('-').map(Number);calendarMonth=new Date(y,m-1,1);renderView();});

document.addEventListener('change',e=>{if(e.target.id==='inquiry-select-all')document.querySelectorAll('.inquiry-select').forEach(x=>x.checked=e.target.checked);});

function refreshTodoRelated(){const type=document.getElementById('f-relatedType'),sel=document.getElementById('f-relatedId'),searchBox=document.getElementById('f-relatedSearch');if(!type||!sel||!searchBox)return;const q=searchBox.value.trim().toLowerCase();const people=type.value==='lead'?state.leads.filter(x=>x.status!=='Converted'):state.clients;const filtered=people.filter(p=>{const ref=type.value==='lead'?leadRef(p):clientRef(p);const cases=type.value==='client'?state.matters.filter(m=>m.clientId===p.id).map(m=>m.ref).join(' '):'';return `${ref} ${p.name||''} ${cases}`.toLowerCase().includes(q)});sel.innerHTML='<option value="">Select a '+(type.value==='lead'?'lead':'client')+'</option>'+filtered.map(p=>`<option value="${esc(p.id)}">${esc(type.value==='lead'?leadRef(p):clientRef(p))} · ${esc(p.name)}</option>`).join('');}
document.addEventListener('input',e=>{if(e.target.id==='f-relatedSearch')refreshTodoRelated()});
document.addEventListener('change',e=>{if(e.target.id==='f-relatedType'){const searchBox=document.getElementById('f-relatedSearch');if(searchBox)searchBox.value='';refreshTodoRelated()}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-account-nav]');if(!button||!isAdmin())return;const target=button.dataset.accountNav;accountingFocus=target;page='reports';search='';filter='All';shell();window.scrollTo(0,0);});

document.addEventListener('click',e=>{const button=e.target.closest('[data-billing-nav]');if(!button)return;if(!canAccess('billing')){toast('Billing access has not been granted.');return;}accountingFocus=null;billingFocus=button.dataset.billingNav;page='billing';search='';filter='All';shell();window.scrollTo(0,0);});

document.addEventListener('click',e=>{const button=e.target.closest('[data-finance-report]');if(!button)return;const target=button.dataset.financeReport;accountingFocus=null;billingFocus=null;page='reports';search='';filter='All';shell();const section=target==='accounting-report'?document.querySelector('[data-report="income"]')?.parentElement:document.querySelector(`[data-finance-section="${target}"]`);section?.scrollIntoView({block:'start'});});

document.addEventListener('click',e=>{const button=e.target.closest('[data-menu-toggle]');if(!button)return;const key=button.dataset.menuToggle;const sidebarOpen=document.querySelector('.sidebar')?.classList.contains('open');openMenu[key]=!openMenu[key];shell();if(sidebarOpen){document.querySelector('.sidebar')?.classList.add('open');document.querySelector('.mobile-overlay')?.classList.add('open');}});

// Browsers block opening data: URLs in a new tab, so sample PDFs are opened through a temporary blob URL.
document.addEventListener('click',e=>{
  const link=e.target.closest('a[href^="data:application/pdf"]');if(!link)return;e.preventDefault();
  try{const [,b64='']=link.getAttribute('href').split(',',2),bytes=Uint8Array.from(atob(b64),ch=>ch.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);}
  catch{toast('Could not open the sample PDF.');}
});

// Register all navigation handlers before drawing the initial page.
shell();
